<?php
declare(strict_types=1);
namespace App\Modules\FreshFood\Controllers;
use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use App\Modules\FreshFood\Services\FreshFoodService;use RuntimeException;use Throwable;
final class FreshFoodController extends Controller {private FreshFoodService $service;private Authorization $authorization;public function __construct(){$this->service=new FreshFoodService();$this->authorization=new Authorization();}private function allow(string $p,string $r='/dashboard'):bool{try{$this->authorization->authorize($p);return true;}catch(RuntimeException $e){flash('error',$e->getMessage());redirect($r);return false;}}public function index():void{if(!$this->allow('fresh_food.view'))return;$this->view('FreshFood::FreshFood.index',['title'=>'Fresh Food','summary'=>$this->service->dashboard((int)Auth::tenantId())]);}public function businesses():void{if(!$this->allow('fresh_food.businesses.view','/fresh-food'))return;$t=(int)Auth::tenantId();$trash=($_GET['view']??'')==='trash';$this->view('FreshFood::Businesses.index',['title'=>$trash?'Deleted Fresh Food Businesses':'Fresh Food Businesses','businesses'=>$this->service->all($t,$trash),'trash'=>$trash]);}public function create():void{if(!$this->allow('fresh_food.businesses.create','/fresh-food/businesses'))return;$this->view('FreshFood::Businesses.create',['title'=>'Add Fresh Food Business','locations'=>$this->service->locations()]);}public function store():void{if(!$this->allow('fresh_food.businesses.create','/fresh-food/businesses'))return;$t=(int)Auth::tenantId();try{$id=$this->service->create($t,$_POST,(int)Auth::id());flash('success','Fresh Food business created successfully.');redirect('/fresh-food/businesses/'.$id);}catch(Throwable $e){$this->view('FreshFood::Businesses.create',['title'=>'Add Fresh Food Business','locations'=>$this->service->locations(),'error'=>$e->getMessage(),'old'=>$_POST]);}}public function show(int $id):void{if(!$this->allow('fresh_food.businesses.view','/fresh-food/businesses'))return;$t=(int)Auth::tenantId();$r=$this->service->find($t,$id);if(!$r)abort(404);$this->view('FreshFood::Businesses.show',['title'=>$r['business_name'],'record'=>$r,'hours'=>$this->service->hours($t,$id)]);}public function edit(int $id):void{if(!$this->allow('fresh_food.businesses.edit','/fresh-food/businesses'))return;$t=(int)Auth::tenantId();$r=$this->service->find($t,$id);if(!$r)abort(404);$this->view('FreshFood::Businesses.edit',['title'=>'Edit Fresh Food Business','record'=>$r,'hours'=>$this->service->hours($t,$id),'locations'=>$this->service->locations()]);}public function update(int $id):void{if(!$this->allow('fresh_food.businesses.edit','/fresh-food/businesses'))return;$t=(int)Auth::tenantId();try{$this->service->update($t,$id,$_POST,(int)Auth::id());flash('success','Fresh Food business updated successfully.');redirect('/fresh-food/businesses/'.$id);}catch(Throwable $e){$r=$this->service->find($t,$id)??$_POST;$this->view('FreshFood::Businesses.edit',['title'=>'Edit Fresh Food Business','record'=>$r,'hours'=>$this->service->hours($t,$id),'locations'=>$this->service->locations(),'error'=>$e->getMessage()]);}}public function hours(int $id):void{if(!$this->allow('fresh_food.businesses.edit','/fresh-food/businesses'))return;$t=(int)Auth::tenantId();try{$this->service->saveHours($t,$id,$_POST,(int)Auth::id());flash('success','Fresh Food hours saved.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/fresh-food/businesses/'.$id.'/edit');}public function destroy(int $id):void{if(!$this->allow('fresh_food.businesses.delete','/fresh-food/businesses'))return;try{$this->service->delete((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Fresh Food business moved to Trash.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/fresh-food/businesses');}public function restore(int $id):void{if(!$this->allow('fresh_food.businesses.delete','/fresh-food/businesses?view=trash'))return;try{$this->service->restore((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Fresh Food business restored.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/fresh-food/businesses?view=trash');}}
